<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {onBackPress} from '@dcloudio/uni-app';
import {catalog,categories,filterStyles,LocalGenerationService,makeRecord,removeRecords,type Style,type DemoRecord} from '../../core/model';
import {loadState,storeState,pickPhoto,releasePhoto,lockModal,setupEscape,setupBack,pushLocalHistory,backLocalHistory,downloadDemo,capsuleInset,setupModalKeyboard,type Photo} from '../../platform';
const state=ref(loadState());const tab=ref('发现');const category=ref('男士');const query=ref('');const detail=ref<Style|null>(null);const galleryDetail=ref<DemoRecord|null>(null);const photo=ref<Photo|null>(null);const error=ref('');const notice=ref('');const loading=ref(false);const advanced=ref(false);const requirements=ref('');const color=ref('保持原色');const demo=ref(false);const result=ref<Style|null>(null);const modal=ref('');const info=ref('');const selectMode=ref(false);const selected=ref<string[]>([]);const compare=ref(false);const scrollTop=ref(0);let rememberedScroll=0;let currentScroll=0;
const options=ref<Record<string,string>>({...state.value.options});
const groups=[{name:'风格类型',items:['职业','时尚','经典','前卫','休闲']},{name:'护理程度',items:['低','中','高']},{name:'偏好长度',items:['短发','中发','长发']},{name:'发色偏好',items:['推荐新色','保持原色']}];
const styles=computed(()=>filterStyles(category.value,query.value));const left=computed(()=>styles.value.filter((_,i)=>i%2===0));const right=computed(()=>styles.value.filter((_,i)=>i%2===1));const inDetail=computed(()=>!!detail.value||!!galleryDetail.value);const inset=capsuleInset();
function persist(){const message=storeState(state.value);if(message)error.value=message;return !message;}
function showInfo(message:string){info.value=message;modal.value='info';}
function closeModal(){modal.value='';}
watch(modal,v=>lockModal(!!v));
watch(options,v=>{if(state.value.rememberOptions){state.value.options={...v};persist();}},{deep:true});
function switchTab(name:string){tab.value=name;error.value='';notice.value='';result.value=null;scrollTop.value=0;currentScroll=0;}
function setCategory(name:string){category.value=name;}
function openStyle(s:Style){rememberedScroll=currentScroll;detail.value=s;scrollTop.value=0;error.value='';result.value=null;pushLocalHistory();}
function openRecord(r:DemoRecord){if(selectMode.value){selected.value=selected.value.includes(r.id)?selected.value.filter(id=>id!==r.id):[...selected.value,r.id];return;}rememberedScroll=currentScroll;galleryDetail.value=r;compare.value=false;scrollTop.value=0;pushLocalHistory();}
function goBack(fromHistory=false){if(modal.value){closeModal();return;}if(inDetail.value){detail.value=null;galleryDetail.value=null;result.value=null;error.value='';scrollTop.value=rememberedScroll;if(!fromHistory)backLocalHistory();}}
const stopModalKeyboard=setupModalKeyboard();const stopBack=setupBack(()=>goBack(true));const stopEscape=setupEscape(()=>modal.value?closeModal():inDetail.value?goBack():undefined);
onBackPress(()=>{if(modal.value||inDetail.value){goBack();return true;}return false;});
onUnmounted(()=>{stopBack();stopEscape();stopModalKeyboard();releasePhoto(photo.value);lockModal(false);});
async function choose(){error.value='';try{const picked=await pickPhoto();if(picked){releasePhoto(photo.value);photo.value=picked;result.value=null;}}catch(e){error.value=e instanceof Error?e.message:'照片无法读取，请重试';}}
function removePhoto(){releasePhoto(photo.value);photo.value=null;result.value=null;}
function start(){error.value='';if(!photo.value){error.value='请先上传您的照片';return;}if(demo.value){modal.value='demo';return;}void generate();}
async function generate(){closeModal();loading.value=true;result.value=null;error.value='';try{await new Promise(r=>setTimeout(r,450));const res=await new LocalGenerationService().generate({photo:photo.value?.url||'',styleId:detail.value?.id,options:{...options.value,...(detail.value?{'发色偏好':color.value}:{})},requirements:requirements.value,demo:demo.value});result.value=res.style;modal.value='result';}catch(e){error.value=e instanceof Error?e.message:'处理失败，请重试';}finally{loading.value=false;}}
function saveResult(){if(!result.value)return;const r=makeRecord({demo:true,style:result.value});state.value.records.unshift(r);if(!persist()){state.value.records.shift();return;}closeModal();notice.value='演示记录已保存；私人照片未持久化';}
function deleteSelected(){const previous=state.value;state.value=removeRecords(state.value,selected.value);if(!persist()){state.value=previous;closeModal();return;}selected.value=[];selectMode.value=false;closeModal();notice.value='已删除所选本地演示记录';}
function toggleSelect(){selectMode.value=!selectMode.value;selected.value=[];}
function hideBanner(){state.value.bannerHidden=true;persist();}
function toggleRemember(){state.value.rememberOptions=!state.value.rememberOptions;if(!state.value.rememberOptions)state.value.options={};else state.value.options={...options.value};persist();}
const previewUrl=computed(()=>modal.value==='photo'?photo.value?.url:modal.value==='galleryPreview'?galleryDetail.value?.image:detail.value?.image);
const beforeImage='/static/catalog/placeholder.svg';
</script>

