     <view v-else class="gallery-grid"><button v-for="r in state.records" :key="r.id" class="gallery-card" :aria-label="'记录 '+r.name" @click="openRecord(r)"><image :src="r.image" mode="aspectFill" /><text v-if="selectMode" class="selection">{{selected.includes(r.id)?'☑':'□'}}</text><text>{{r.name}}</text><text class="demo-badge">演示 · 非 AI 生成</text><text class="muted">{{new Date(r.created).toLocaleDateString()}}</text></button></view>
     <button v-if="selectMode" class="danger wide" :disabled="!selected.length" @click="modal='delete'">删除所选（{{selected.length}}）</button>
    </template>
    <template v-else-if="tab==='个人资料'">
     <text class="eyebrow">ACCOUNT</text><view class="profile-heading"><text class="page-title">个人资料</text><text class="credits">♢ 0</text></view><text class="description">管理您的账户和偏好设置</text>
     <view class="plan-panel"><view class="plan-title"><image src="/static/icons/gift.svg" /><text class="section-title">免费计划</text></view><text class="description">升级以解锁所有功能</text><button class="gold wide" @click="showInfo('订阅和支付未连接。本地研究不会购买、扣费或创建账户。')">↑ 升级至高级版</button><view class="plan-line" /></view>
     <button class="setting-row" @click="showInfo('本地邀请演示：积分与分享服务未连接，不会发送邀请。')"><image class="setting-icon" src="/static/icons/gift.svg" /><view><text>邀请好友</text><text class="muted">每位朋友试用可赚 30 个积分</text></view><text class="chevron">›</text></button>
     <button class="setting-row" @click="showInfo('邀请码兑换未连接，不会领取或更改积分。')"><image class="setting-icon" src="/static/icons/ticket.svg" /><view><text>输入邀请码</text><text class="muted">已有邀请码？领取 30 免费积分</text></view><text class="chevron">›</text></button>
     <button class="setting-row" @click="modal='language'"><image class="setting-icon" src="/static/icons/language.svg" /><view><text>语言</text><text class="muted">更改应用程序语言</text></view><text class="language-value">简体中文</text><text class="chevron">›</text></button>
     <button class="setting-row" @click="showInfo('这是仅监听 127.0.0.1 的本地研究预览，未公开发布，不发送分享。')"><image class="setting-icon" src="/static/icons/share.svg" /><view><text>分享应用</text><text class="muted">告诉朋友 HAIRAI STUDIO</text></view><text class="chevron">›</text></button>
     <button class="setting-row" @click="showInfo('反馈服务未连接；您输入的数据和照片不会发送到新服务。')"><text class="setting-icon">♧</text><view><text>发送反馈</text><text class="muted">帮助我们改进 HAIRAI STUDIO</text></view><text class="chevron">›</text></button>
     <button class="setting-row" @click="modal='settings'"><text class="setting-icon">⚙</text><view><text>本地设置</text><text class="muted">隐私与偏好</text></view><text class="chevron">›</text></button>
     <view class="brand"><text>HairAI · 本地研究</text><text class="muted">版本 0.1.0 · 非官方</text><text class="muted">账户、积分、订阅、真实 AI 均未连接</text></view>
    </template>
    <template v-if="detail||(!inDetail&&tab==='AI匹配')">
     <view class="photo-area" v-if="photo"><image :src="photo.url" mode="aspectFit" @click="modal='photo'" /><button aria-label="移除照片" class="remove-photo" @click="removePhoto">×</button><button class="replace-photo" @click="choose">更换照片</button></view>
     <button v-else class="photo-empty" @click="choose"><text class="empty-icon">＋</text><text>选择本地照片</text><text class="muted">JPG / PNG / WebP · 最大 8 MB</text></button>
     <text class="privacy">照片仅在本机临时使用，不上传，不保存到画廊。刷新后清除。</text>
     <template v-if="!detail"><text class="section-title tips-title">最佳效果提示</text><view class="tips"><view v-for="(tip,i) in ['使用清晰、光线充足的照片','面部应清晰可见','避免使用重滤镜或浓妆']" :key="tip"><text class="muted">0{{i+1}}</text><text>{{tip}}</text></view></view><button class="advanced-toggle" @click="advanced=!advanced"><view><text class="section-title">高级选项（可选）</text><text class="muted">{{Object.values(options).filter(Boolean).join(' · ')||'未选择偏好'}}</text></view><text>{{advanced?'⌃':'⌄'}}</text></button><view v-if="advanced" class="advanced"><view v-for="g in groups" :key="g.name" class="option-group"><text class="eyebrow">{{g.name}}</text><view class="chips"><button v-for="item in g.items" :key="item" class="outline" :class="{chosen:options[g.name]===item}" @click="options[g.name]=options[g.name]===item?'':item">{{item}}</button></view></view></view></template>
     <template v-else><text class="section-title">发色偏好</text><view class="chips"><button v-for="c in ['保持原色','乌黑色','棕色','金色']" :key="c" class="outline" :class="{chosen:color===c}" @click="color=c">{{c}}</button></view></template>
